// Implement Queue using Two Stacks
struct QueueWithStacks {
    var stack1 = AnimatedStack<Int>()
    var stack2 = AnimatedStack<Int>()

    mutating func enqueue(_ val: Int) {
        stack1.push(val)
    }

    mutating func dequeue() -> Int? {
        if stack2.isEmpty {
            while !stack1.isEmpty {
                if let popped = stack1.pop() {
                    stack2.push(popped)
                }
            }
        }
        return stack2.pop()
    }
}

var queue = QueueWithStacks()
queue.enqueue(10)
queue.enqueue(20)
queue.enqueue(30)
let firstOut = queue.dequeue()
